CREATE TABLE outbox_mutations (id TEXT PRIMARY KEY, object_type TEXT NOT NULL CHECK (object_type IN ('task', 'version')), object_id TEXT NOT NULL, field TEXT NOT NULL, expected_before TEXT, target TEXT NOT NULL, actor TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('pending', 'confirmed', 'expired', 'failed')), expires_at TEXT NOT NULL, created_at TEXT NOT NULL, confirmed_at TEXT);
